const t = phi.tabs.open("https://www.carmax.com/");
phi.narrate("Opening CarMax");
return t;

const r = phi.fill("1", "2022 Tesla Model 3");
phi.press("Enter");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
return { fill: r, url: phi.observe({maxElements:5}).url, title: phi.text().slice(0, 300) };

const r = phi.fill("#header-inventory-search", "2022 Tesla Model 3");
phi.press("Enter");
phi.waitForNetworkIdle({ timeoutMs: 10000 });
const o = phi.observe({ maxElements: 40 });
return { fill: r, url: o.url, title: o.title, nodes: o.nodes.map(n => n.ref + " " + n.role + " " + (n.name || n.text || "")).slice(0, 40) };

const cards = phi.query("div[class*='card'], article, li[class*='result']", { limit: 5, fields: ["class","text"] });
const links = phi.query("a[href*='/car/']", { limit: 20, fields: ["href","text"] });
return { cardsTotal: cards.total, cards: cards.items.map(c => (c.text||"").slice(0,400)), linksTotal: links.total, links: links.items.slice(0,20) };

const t = phi.tabs.open("https://www.carmax.com/car/70280293");
phi.sleep(3000);
phi.waitForNetworkIdle({ timeoutMs: 15000 });
const o = phi.observe({ maxElements: 40 });
return { tab: t, url: o.url, title: o.title, text: (o.text||"").slice(0, 1500) };

const t = phi.text();
const specs = phi.query("[class*='spec'], [class*='Spec'], [class*='detail'], [class*='Detail']", { limit: 30, fields: ["text"] });
const dl = phi.query("dl", { limit: 5, fields: ["text"] });
return { title: phi.observe({viewportOnly:true}).title, textHead: (t||"").slice(0, 3000), specs: specs.items.map(s=>(s.text||"").slice(0,150)).filter(Boolean).slice(0,20), dl: dl.items.map(d=>(d.text||"").slice(0,300)) };

const o = phi.observe({ viewportOnly: true, maxElements: 25 });
phi.keep("listing", {
  url: "https://www.carmax.com/car/70280293",
  title: "Used 2022 Tesla Model 3 in LAX, CA | CarMax",
  stock: "70280293",
  vin: "5YJ3E1EAXNF252479",
  price: "$32,998 (was $33,998)",
  miles: "58k miles",
  location: "CarMax LAX, CA (store 90301)",
  drivetrain: "Rear Wheel Drive, Electric, 50 kWh battery, 263 mi range (when new)",
  colors: "Gray exterior / Black interior",
  availability: "Available today, free reservation, test drive at CarMax LAX",
  otherListings2022Model3: ["70282166 ($31,998, 20k mi, free shipping)", "70281287 Long Range ($34,998, 29k mi)", "70161984 Long Range ($28,998, 63k mi, free shipping)", "70288274 Long Range ($31,998, 54k mi, free shipping)"]
});
return { url: o.url, title: o.title, firstNodes: o.nodes.slice(0, 15).map(n => n.role + " | " + (n.name || n.text || "").slice(0, 80)) };

const o = phi.observe({ viewportOnly: true, maxElements: 10 });
const t = phi.text() || "";
const has = { year: /2022/.test(t), model: /Model 3/.test(t), price: (t.match(/\$3[0-9],\d{3}/g)||[]).slice(0,4) };
phi.keep("listing", {
  url: "https://www.carmax.com/car/70280293",
  title: o.title,
  stock: "70280293",
  vin: "5YJ3E1EAXNF252479",
  price: "$32,998 ($33,998 before a $1,000 cut on Oct 15, 2026)",
  miles: "58k miles",
  location: "CarMax LAX, CA (store 90301), available today, free reservation",
  specs: "Rear Wheel Drive, Electric, 50 kWh battery, 263 mi range (when new), Gray exterior / Black interior",
  other2022Model3: ["70282166 $31,998 20k mi", "70281287 Long Range $34,998 29k mi", "70161984 Long Range $28,998 63k mi", "70288274 Long Range $31,998 54k mi"]
});
return { url: o.url, title: o.title, has, top: t.slice(0, 320) };

const seen = phi.readImage(undefined, "What car is shown — year, make and model — and what price and mileage are displayed?");
phi.keep("listing_check", { onScreen: String(seen).slice(0, 500) });
return { seen: String(seen).slice(0, 600) };

const q = phi.query("h1, h2", { limit: 10 });
const t = phi.text() || "";
const idx = t.indexOf("2022 Tesla Model 3");
phi.keep("listing_final", {
  url: "https://www.carmax.com/car/70280293",
  title: "Used 2022 Tesla Model 3 in LAX, CA | CarMax",
  stock: "70280293",
  vin: "5YJ3E1EAXNF252479",
  price: "$32,998 (was $33,998)",
  miles: "58k miles",
  location: "CarMax LAX, CA (store 90301)",
  specs: "Rear Wheel Drive, Electric, 50 kWh battery, 263 mi range (when new), Gray exterior / Black interior, available today, free reservation",
  other2022Model3: ["70282166 $31,998 20k mi", "70281287 LR $34,998 29k mi", "70161984 LR $28,998 63k mi", "70288274 LR $31,998 54k mi"]
});
phi.look();
return { headings: q.items.map(i => i.text.slice(0, 90)), snippet: idx >= 0 ? t.slice(idx, idx + 120) : t.slice(0, 200) };
